// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice Efficient Base64 encoding and decoding library.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/Base64.sol)
library Base64 {
    /// @notice Encodes the given data into a Base64 string, with options for file-safe encoding and padding.
    /// @param data The input data to be encoded.
    /// @param fileSafe If true, uses a file-safe Base64 alphabet (replaces '+' and '/' with '-' and '_').
    /// @param noPadding If true, removes the padding characters ('=') from the output.
    /// @return result The Base64 encoded string.
    function encode(bytes memory data, bool fileSafe, bool noPadding)
        internal
        pure
        returns (string memory result)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let dataLength := mload(data)

            if dataLength {
                let encodedLength := shl(2, div(add(dataLength, 2), 3))

                result := mload(0x40)
                mstore(result, encodedLength)

                // Store the lookup table in scratch space.
                // Standard: ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/
                // File-safe: ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_
                mstore8(0, 65)    // A
                mstore8(1, 66)    // B
                mstore8(2, 67)    // C
                mstore8(3, 68)    // D
                mstore8(4, 69)    // E
                mstore8(5, 70)    // F
                mstore8(6, 71)    // G
                mstore8(7, 72)    // H
                mstore8(8, 73)    // I
                mstore8(9, 74)    // J
                mstore8(10, 75)   // K
                mstore8(11, 76)   // L
                mstore8(12, 77)   // M
                mstore8(13, 78)   // N
                mstore8(14, 79)   // O
                mstore8(15, 80)   // P
                mstore8(16, 81)   // Q
                mstore8(17, 82)   // R
                mstore8(18, 83)   // S
                mstore8(19, 84)   // T
                mstore8(20, 85)   // U
                mstore8(21, 86)   // V
                mstore8(22, 87)   // W
                mstore8(23, 88)   // X
                mstore8(24, 89)   // Y
                mstore8(25, 90)   // Z
                mstore8(26, 97)   // a
                mstore8(27, 98)   // b
                mstore8(28, 99)   // c
                mstore8(29, 100)  // d
                mstore8(30, 101)  // e
                mstore8(31, 102)  // f
                mstore8(32, 103)  // g
                mstore8(33, 104)  // h
                mstore8(34, 105)  // i
                mstore8(35, 106)  // j
                mstore8(36, 107)  // k
                mstore8(37, 108)  // l
                mstore8(38, 109)  // m
                mstore8(39, 110)  // n
                mstore8(40, 111)  // o
                mstore8(41, 112)  // p
                mstore8(42, 113)  // q
                mstore8(43, 114)  // r
                mstore8(44, 115)  // s
                mstore8(45, 116)  // t
                mstore8(46, 117)  // u
                mstore8(47, 118)  // v
                mstore8(48, 119)  // w
                mstore8(49, 120)  // x
                mstore8(50, 121)  // y
                mstore8(51, 122)  // z
                mstore8(52, 48)   // 0
                mstore8(53, 49)   // 1
                mstore8(54, 50)   // 2
                mstore8(55, 51)   // 3
                mstore8(56, 52)   // 4
                mstore8(57, 53)   // 5
                mstore8(58, 54)   // 6
                mstore8(59, 55)   // 7
                mstore8(60, 56)   // 8
                mstore8(61, 57)   // 9
                if fileSafe {
                    mstore8(62, 45)  // -
                    mstore8(63, 95)  // _
                }
                if iszero(fileSafe) {
                    mstore8(62, 43)  // +
                    mstore8(63, 47)  // /
                }

                let o := add(result, 0x20)
                let end := add(add(data, 0x20), dataLength)

                for {} 1 {} {
                    data := add(data, 3)
                    let input := mload(data)

                    // Extract 6-bit indices and look up from table.
                    mstore8(o,       mload(and(shr(18, input), 0x3F)))
                    mstore8(add(o, 1), mload(and(shr(12, input), 0x3F)))
                    mstore8(add(o, 2), mload(and(shr(6,  input), 0x3F)))
                    mstore8(add(o, 3), mload(and(input,           0x3F)))
                    o := add(o, 4)

                    if iszero(lt(data, end)) { break }
                }

                // Handle padding.
                let remainder := mod(dataLength, 3)
                if remainder {
                    if noPadding {
                        mstore(result, sub(encodedLength, sub(3, remainder)))
                    }
                    if iszero(noPadding) {
                        if eq(remainder, 1) {
                            mstore8(sub(o, 2), 0x3d) // '='
                        }
                        mstore8(sub(o, 1), 0x3d) // '='
                    }
                }

                // Zeroize scratch space.
                mstore(0x00, 0)
                mstore(0x20, 0)

                // Set the free memory pointer and null terminator.
                let paddedEnd := add(result, add(0x20, encodedLength))
                mstore(paddedEnd, 0)
                mstore(0x40, and(add(paddedEnd, 31), not(31)))
