    /// @notice Encodes the given data into a Base64 string.
    /// @param data The input data to be encoded.
    /// @return result The Base64 encoded string.
    function encode(bytes memory data) internal pure returns (string memory result) {
        result = encode(data, false, false);
    }

    /// @notice Encodes the given data into a Base64 string, with option for file-safe encoding.
    /// @param data The input data to be encoded.
    /// @param fileSafe If true, uses a file-safe Base64 alphabet (replaces '+' and '/' with '-' and '_').
    /// @return result The Base64 encoded string.
    function encode(bytes memory data, bool fileSafe)
        internal
        pure
        returns (string memory result)
    {
        result = encode(data, fileSafe, false);
    }

    /// @notice Decodes a base64 encoded string into bytes.
    /// @param data The base64 encoded string to decode.
    /// @return result The decoded bytes.
    function decode(string memory data) internal pure returns (bytes memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let dataLength := mload(data)

            if dataLength {
                // Approximate decoded length.
                let decodedLength := add(div(mul(dataLength, 3), 4), 3)
                result := mload(0x40)
                mstore(result, decodedLength)

                // Build reverse lookup table in scratch space: maps ASCII to Base64 index (0-63).
                // Invalid characters will be mapped to 0xFF.
                {
                    // Initialize all to 0xFF (invalid).
                    for { let i := 0 } lt(i, 256) { i := add(i, 1) } {
                        mstore8(i, 0xFF)
                    }
                    // A-Z -> 0-25
                    for { let i := 65 } lt(i, 91) { i := add(i, 1) } {
                        mstore8(i, sub(i, 65))
                    }
                    // a-z -> 26-51
                    for { let i := 97 } lt(i, 123) { i := add(i, 1) } {
                        mstore8(i, sub(i, 71))
                    }
                    // 0-9 -> 52-61
                    for { let i := 48 } lt(i, 58) { i := add(i, 1) } {
                        mstore8(i, add(i, 4))
                    }
                    // + -> 62
                    mstore8(43, 62)
                    // / -> 63
                    mstore8(47, 63)
                    // - -> 62 (file-safe variant of +)
                    mstore8(45, 62)
                    // _ -> 63 (file-safe variant of /)
                    mstore8(95, 63)
                }

                let o := add(result, 0x20)
                let end := add(add(data, 0x20), dataLength)
                let i := add(data, 0x20)

                for {} lt(i, end) {} {
                    let c0 := byte(0, mload(i))
                    let c1 := byte(0, mload(add(i, 1)))
                    let c2 := byte(0, mload(add(i, 2)))
                    let c3 := byte(0, mload(add(i, 3)))

                    let b0 := mload(c0)
                    let b1 := mload(c1)
                    let b2 := mload(c2)
                    let b3 := mload(c3)

                    // Check for padding '=' (0x3d).
                    if eq(c2, 0x3d) {
                        // 2 padding chars -> 1 output byte.
                        mstore8(o, or(shl(2, and(b0, 0x3F)), shr(4, and(b1, 0x3F))))
                        o := add(o, 1)
                        i := add(i, 4)
                        break
                    }
                    if eq(c3, 0x3d) {
                        // 1 padding char -> 2 output bytes.
                        mstore8(o, or(shl(2, and(b0, 0x3F)), shr(4, and(b1, 0x3F))))
                        mstore8(add(o, 1), or(shl(4, and(b1, 0x0F)), shr(2, and(b2, 0x3F))))
                        o := add(o, 2)
                        i := add(i, 4)
                        break
                    }

                    // No padding -> 3 output bytes.
                    mstore8(o, or(shl(2, and(b0, 0x3F)), shr(4, and(b1, 0x3F))))
                    mstore8(add(o, 1), or(shl(4, and(b1, 0x0F)), shr(2, and(b2, 0x3F))))
                    mstore8(add(o, 2), or(shl(6, and(b2, 0x03)), and(b3, 0x3F)))
                    o := add(o, 3)
                    i := add(i, 4)
                }

                // Restore scratch space.
                mstore(0x00, 0)
                mstore(0x20, 0)

                // Set the actual decoded length.
                let actualLength := sub(o, add(result, 0x20))
                mstore(result, actualLength)

                // Zeroize the trailing bytes.
                mstore(o, 0)

                // Set the free memory pointer.
                mstore(0x40, and(add(o, 31), not(31)))
            }
        }
    }
}

