pragma solidity ^0.8.4;

/// @notice Efficient Base64 encoding and decoding library.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/Base64.sol)
library Base64 {
    /// @notice Encodes the given data into a Base64 string, with options for file-safe encoding and padding.
    /// @param data The input data to be encoded.
    /// @param fileSafe If true, uses a file-safe Base64 alphabet (replaces '+' and '/' with '-' and '_').
    /// @param noPadding If true, removes the padding characters ('=') from the output.
    /// @return result The Base64 encoded string.
    function encode(bytes memory data, bool fileSafe, bool noPadding)
        internal
        pure
        returns (string memory result)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let dataLength := mload(data)

            if dataLength {
                let encodedLength := shl(2, div(add(dataLength, 2), 3))

                result := add(mload(0x40), 0x20)
                mstore(result, encodedLength)

                let table := "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdef"
                "ghijklmnopqrstuvwxyz0123456789+/"

                if fileSafe {
                    table := "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdef"
                    "ghijklmnopqrstuvwxyz0123456789-_"
                }

                // Write the table to the scratch space.
                mstore(0x1f, add(table, 1))

                // Write the first 3 bytes of the table at `0x20` offset (scratch space).
                // `0x40` will be used as scratch space for the encoding.
                let end := add(add(data, 0x20), dataLength)
                let o := add(result, 0x20)

                for {} 1 {} {
                    // Read 3 bytes.
                    data := add(data, 3)
                    let input := mload(data)

                    // Write 4 bytes.
                    mstore8(o, mload(and(shr(18, input), 0x3F)))
                    mstore8(add(o, 1), mload(and(shr(12, input), 0x3F)))
                    mstore8(add(o, 2), mload(and(shr(6, input), 0x3F)))
                    mstore8(add(o, 3), mload(and(input, 0x3F)))
                    o := add(o, 4)

                    if iszero(lt(data, end)) { break }
                }

                // Handle padding.
                let remainder := mod(dataLength, 3)
                if remainder {
                    if noPadding {
                        mstore(result, sub(encodedLength, sub(3, remainder)))
                    }
                    if iszero(noPadding) {
                        if eq(remainder, 1) {
                            mstore8(sub(o, 2), 0x3d) // '='
                        }
                        mstore8(sub(o, 1), 0x3d) // '='
                    }
                }

                // Set the free memory pointer.
                mstore(add(result, add(0x20, encodedLength)), 0)
                mstore(0x40, and(add(add(result, 0x40), encodedLength), not(31)))
            }
        }
    }

    /// @notice Encodes the given data into a Base64 string.
    /// @param data The input data to be encoded.
    /// @return result The Base64 encoded string.
    function encode(bytes memory data) internal pure returns (string memory result) {
        result = encode(data, false, false);
    }

    /// @notice Encodes the given data into a Base64 string, with option for file-safe encoding.
    /// @param data The input data to be encoded.
    /// @param fileSafe If true, uses a file-safe Base64 alphabet (replaces '+' and '/' with '-' and '_').
    /// @return result The Base64 encoded string.
    function encode(bytes memory data, bool fileSafe)
        internal
        pure
        returns (string memory result)
    {
        result = encode(data, fileSafe, false);
    }

    /// @notice Decodes a base64 encoded string into bytes.
    /// @param data The base64 encoded string to decode.
    /// @return result The decoded bytes.
    function decode(string memory data) internal pure returns (bytes memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let dataLength := mload(data)

            if dataLength {
                // Approximate decoded length.
                let decodedLength := add(div(mul(dataLength, 3), 4), 3)
                result := mload(0x40)
