                // Invalid characters get mapped to 0xFF.
                // We use the scratch space from 0x00 to 0xFF for this.
                {
                    // Initialize all to 0xFF (invalid).
                    for { let i := 0 } lt(i, 256) { i := add(i, 1) } {
                        mstore8(i, 0xFF)
                    }

                    // A-Z -> 0-25
                    for { let i := 65 } lt(i, 91) { i := add(i, 1) } {
                        mstore8(i, sub(i, 65))
                    }
                    // a-z -> 26-51
                    for { let i := 97 } lt(i, 123) { i := add(i, 1) } {
                        mstore8(i, sub(i, 71))
                    }
                    // 0-9 -> 52-61
                    for { let i := 48 } lt(i, 58) { i := add(i, 1) } {
                        mstore8(i, add(i, 4))
                    }
                    // + -> 62
                    mstore8(43, 62)
                    // / -> 63
                    mstore8(47, 63)
                    // - -> 62 (file-safe)
                    mstore8(45, 62)
                    // _ -> 63 (file-safe)
                    mstore8(95, 63)
                }

                let o := add(result, 0x20)
                let end := add(add(data, 0x20), dataLength)
                let i := add(data, 0x20)

                for {} lt(i, end) {} {
                    // Read 4 characters (3 bytes of output).
                    let c0 := and(mload(i), 0xFF)
                    let c1 := and(mload(add(i, 1)), 0xFF)
                    let c2 := and(mload(add(i, 2)), 0xFF)
                    let c3 := and(mload(add(i, 3)), 0xFF)

                    let b0 := mload(c0)
                    let b1 := mload(c1)
                    let b2 := mload(c2)
                    let b3 := mload(c3)

                    // Check for padding '=' (0x3d).
                    if eq(c2, 0x3d) {
                        // 2 padding chars -> 1 output byte.
                        mstore8(o, or(shl(2, and(b0, 0x3F)), shr(4, and(b1, 0x3F))))
                        o := add(o, 1)
                        i := add(i, 4)
                        // Skip rest.
                        break
                    }
                    if eq(c3, 0x3d) {
                        // 1 padding char -> 2 output bytes.
                        mstore8(o, or(shl(2, and(b0, 0x3F)), shr(4, and(b1, 0x3F))))
