                        i := add(i, 4)
                        // Skip rest.
                        break
                    }

                    // 3 output bytes.
                    mstore8(o, or(shl(2, and(b0, 0x3F)), shr(4, and(b1, 0x3F))))
                    mstore8(add(o, 1), or(shl(4, and(b1, 0x0F)), shr(2, and(b2, 0x3F))))
                    mstore8(add(o, 2), or(shl(6, and(b2, 0x03)), and(b3, 0x3F)))
                    o := add(o, 3)
                    i := add(i, 4)
                }

                // Restore scratch space.
                mstore(0x00, 0)
                mstore(0x20, 0)

                // Set the actual decoded length.
                let actualLength := sub(o, add(result, 0x20))
                mstore(result, actualLength)

                // Zeroize the trailing bytes.
                mstore(o, 0)

                // Set the free memory pointer.
                mstore(0x40, and(add(o, 31), not(31)))
            }
        }
    }
}

